/*==================[macros]================================================*/

/*------------------[Service identifiers]------------------------------------*/
/** \brief Definition of the service Id of Icu_Init */
#define ICU_API_INIT                      0x00U

/** \brief Definition of the service Id of Icu_DeInit */
#define ICU_API_DE_INIT                   0x01U

/** \brief Definition of the service Id of Icu_SetMode */
#define ICU_API_SET_MODE                  0x02U

/** \brief Definition of the service Id of Icu_DisableWakeup */
#define ICU_API_DISABLE_WAKEUP            0x03U

/** \brief Definition of the service Id of Icu_EnableWakeup */
#define ICU_API_ENABLE_WAKEUP             0x04U

/** \brief Definition of the service Id of Icu_ActivationCondition */
#define ICU_API_SET_ACTIVATION_CONDITION  0x05U

/** \brief Definition of the service Id of Icu_DisableNotification */
#define ICU_API_DISABLE_NOTIFICATION      0x06U

/** \brief Definition of the service Id of Icu_EnableNotification */
#define ICU_API_ENABLE_NOTIFICATION       0x07U

/** \brief Definition of the service Id of Icu_GetInputState */
#define ICU_API_GET_INPUT_STATE           0x08U

/** \brief Definition of the service Id of Icu_StartTimestamp */
#define ICU_API_START_TIMESTAMP           0x09U

/** \brief Definition of the service Id of Icu_StopTimestamp */
#define ICU_API_STOP_TIMESTAMP            0x0AU

/** \brief Definition of the service Id of Icu_GetTimestampIndex */
#define ICU_API_GET_TIMESTAMP_INDEX       0x0BU

/** \brief Definition of the service Id of Icu_ResetEdgeCount */
#define ICU_API_RESET_EDGE_COUNT          0x0CU

/** \brief Definition of the service Id of Icu_EnableEdgeCount */
#define ICU_API_ENABLE_EDGE_COUNT         0x0DU

/** \brief Definition of the service Id of Icu_DisableEdgeCount */
#define ICU_API_DISABLE_EDGE_COUNT        0x0EU

/** \brief Definition of the service Id of Icu_GetEdgeNumbers */
#define ICU_API_GET_EDGE_NUMBERS          0x0FU

/** \brief Definition of the service Id of Icu_GetTimeElapsed */
#define ICU_API_GET_TIME_ELAPSED          0x10U

/** \brief Definition of the service Id of Icu_GetDutyCycleValues */
#define ICU_API_GET_DUTY_CYCLE_VALUES     0x11U

/** \brief Definition of the service Id of Icu_GetVersionInfo */
#define ICU_API_GET_VERSION_INFO          0x12U

/** \brief Definition of the service Id of Icu_StartSignalMeasurement */
#define ICU_API_START_SIGNAL_MEAS         0x13U

/** \brief Definition of the service Id of Icu_StopSignalMeasurement */
#define ICU_API_STOP_SIGNAL_MEAS          0x14U

/** \brief Definition of the service Id of Icu_CheckWakeup */
#define ICU_API_CHECK_WAKEUP              0x15U

/** \brief Definition of the service Id of Icu_EnableEdgeDetection  */
#define ICU_API_ENABLE_EDGE_DETECTION     0x16U

/** \brief Definition of the service Id of Icu_DisableEdgeDetection  */
#define ICU_API_DISABLE_EDGE_DETECTION    0x17U

/** \brief Definition of the service Id of Icu_CheckChannelStatus  */
#define ICU_API_CHECK_CHANNEL_STATUS      0xFFU

/*------------------[Development errors]-------------------------------------*/
/** \brief API Icu_Init service called with wrong parameter */
#define ICU_E_PARAM_CONFIG                0x0AU
/** \brief API service used with an invalid channel identifier or channel was not configured for the functionality of the calling API */
#define ICU_E_PARAM_CHANNEL               0x0BU
/** \brief API service used with an invalid or not feasible activation */
#define ICU_E_PARAM_ACTIVATION            0x0CU
/** \brief API service used with an invalid application-buffer pointer */
#define ICU_E_PARAM_BUFFER_PTR            0x0DU
/** \brief API service used with an invalid buffer size */
#define ICU_E_PARAM_BUFFER_SIZE           0x0EU
/** \brief API service Icu_SetMode used with an invalid mode */
#define ICU_E_PARAM_MODE                  0x0FU
/** \brief API service used without module initialization */
#define ICU_E_UNINIT                      0x14U
/** \brief API service Icu_StopTimestamp called on a channel which was not started or already stopped */
#define ICU_E_NOT_STARTED                 0x15U
/** \brief API service Icu_SetMode is called while a running operation */
#define ICU_E_BUSY_OPERATION              0x16U
/** \brief API service Icu_Init is called when driver state is already initialised. */
#define ICU_E_ALREADY_INITIALIZED         0x17U
/** \brief API service used with an invalid notify interval */
#define ICU_E_PARAM_NOTIFY_INTERVAL       0x18U
/** \brief API service used with an invalid version-info pointer */
#define ICU_E_PARAM_VINFO                 0x19U
/** \brief API service used with an invalid CheckChannelStatusPtr pointer */
#define ICU_E_PARAM_CHECK_STATUS_POINTER  0x20U
/** \brief API service used with a register corruption  */
#define ICU_E_REGISTER                    0x21U

/*------------------------[Configuration settings]---------------------------*/
/* Definition of the S6J3 ICU Resource type. */
#define ICU_32BIT_ICU                    ((uint8)0x00u)
#define ICU_EXTINT                       ((uint8)0x01u)

/* Definition of the channel status of an ICU channel. */
#define ICU_NOT_STARTED                  ((uint8)0x00u)  /* the channel has not been started/enabled yet */
#define ICU_RUNNING                      ((uint8)0x01u)  /* the channel has been started/enabled and is running */
#define ICU_STOPPED                      ((uint8)0x02u)  /* the channel has been stopped/disabled and is not running */

